import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, define P as the product over k from 1 to {n} of (k!) raised to the power ({r}*k + {s}). Let Z be the number of trailing zeros at the right end of the base-{base} representation of P. Compute Z modulo {mod}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate parameters for a harder generalization:
# P = ∏_{k=1}^n (k!)^{r*k + s}
# trailing zeros in base 'base' modulo 'mod'
n = rng.randint(200, 3000)
r = rng.randint(1, 6)
s = rng.randint(0, 12)
# Build a composite base from small primes with at least two distinct prime factors
primes_pool = [2, 3, 5, 7]
num_primes = rng.choice([2, 3])
chosen_primes = rng.sample(primes_pool, num_primes)
exps = [rng.randint(1, 4) for _ in chosen_primes]
base = 1
for p, e in zip(chosen_primes, exps):
    base *= (p ** e)
# Choose a nontrivial modulus
mod_choices = [1000, 2000, 2500, 5000, 10000, 12000, 20000, 30000, 40000, 50000, 65536, 99991]
mod = rng.choice(mod_choices)
return {'n': n, 'r': r, 's': s, 'base': base, 'mod': mod}

    def verifier(assign):
# Validate and compute Z modulo mod
# P = ∏_{k=1}^n (k!)^{r*k + s}
# Z = min_{p^e || base} v_p(P) // e, where v_p(P) = Σ_{k=1}^n (r*k + s) v_p(k!)
# v_p(k!) = Σ_{j>=1} floor(k / p^j)
# We compute Σ_{k=1}^n floor(k / h) and Σ_{k=1}^n k * floor(k / h) efficiently using closed forms.
try:
    n = int(assign.get('n', None))
    r = int(assign.get('r', None))
    s = int(assign.get('s', None))
    base = int(assign.get('base', None))
    mod = int(assign.get('mod', None))
except Exception:
    # invalid types
    return (False, None)
# Domain checks to prevent trivial/easy instances
if not (isinstance(n, int) and isinstance(r, int) and isinstance(s, int) and isinstance(base, int) and isinstance(mod, int)):
    # types must be ints
    return (False, None)
if n < 50 or r < 1 or s < 0 or base < 6 or mod < 2:
    # enforce nontrivial ranges
    return (False, None)
# Factorize base and ensure at least two distinct prime factors
def factorize(x):
    d = {}
    temp = x
    # factor out 2
    cnt = 0
    while temp % 2 == 0:
        temp //= 2
        cnt += 1
    if cnt:
        d[2] = cnt
    f = 3
    while f * f <= temp:
        cnt = 0
        while temp % f == 0:
            temp //= f
            cnt += 1
        if cnt:
            d[f] = cnt
        f += 2
    if temp > 1:
        d[temp] = d.get(temp, 0) + 1
    return d
base_fac = factorize(base)
if len(base_fac) < 2:
    # must have at least two distinct primes in the base to enforce minimization across valuations
    return (False, None)
# Closed forms for sums S1(n,h) = Σ_{k=1}^n floor(k/h) and S2(n,h) = Σ_{k=1}^n k*floor(k/h)
def S1(n, h):
    T = n // h
    if T == 0:
        return 0
    # S1 = T*(n+1) - h*T*(T+1)/2
    return T * (n + 1) - (h * T * (T + 1)) // 2
def S2(n, h):
    T = n // h
    if T == 0:
        return 0
    S_total = n * (n + 1) // 2
    # sum_t = Σ t, sum_t2 = Σ t^2, t=1..T
    sum_t = T * (T + 1) // 2
    sum_t2 = T * (T + 1) * (2 * T + 1) // 6
    E = h * h * sum_t2 - h * sum_t  # equals Σ (t*h*(t*h - 1))
    return T * S_total - (E // 2)   # exact integer since each term t*h*(t*h-1) is even
# Compute v_p(P) for each prime dividing base
def v_p_of_P(p):
    v = 0
    q = p
    while q <= n:
        # accumulate contributions from floor divisions by q = p^j
        s1 = S1(n, q)
        s2 = S2(n, q)
        v += r * s2 + s * s1
        # next power
        if q > n // p:
            break
        q *= p
    return v
# trailing zeros count in base 'base'
Z_candidates = []
for p, e in base_fac.items():
    vp = v_p_of_P(p)
    Z_candidates.append(vp // e)
Z = min(Z_candidates)
answer = Z % mod
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

